/* ══════════ 目录颜色编号（v4 T-03）══════════
 * 用户要求：目录/文件夹竖排的每一行按出现顺序换色，不是固定一种；
 * 可自定义添加；先给两套随机色。
 * 生成方式：HSL 均匀取色，保证相邻两项色差足够大。
 * ═══════════════════════════════════════════════════════ */
function treeRing(hueStart, sat, light, n) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const h = (hueStart + (360 / n) * i) % 360;
    out.push(`hsl(${h.toFixed(0)} ${sat}% ${light}%)`);
  }
  return out;
}

