const ANIM_EXT_RE = /\.(gif|webp|apng)$/i;

function isVideoSrc(src) { return VIDEO_EXT_RE.test(String(src || "").split("?")[0]); }
function isAnimSrc(src) { return ANIM_EXT_RE.test(String(src || "").split("?")[0]); }

